export const recordedAudioBoundaryIds = new Set(Object.keys(measuredBoundarySilenceMsById));
export const standaloneBoundarySilenceMs = 100;
export const sequenceBoundarySilenceMs = 60;

export function recordedAudioPlaybackWindow(source, retainedSilenceMs = standaloneBoundarySilenceMs) {
  const id = /\/([a-f0-9]{12})\.mp3(?:$|[?])/u.exec(String(source ?? ""))?.[1];
  const silence = measuredBoundarySilenceMsById[id];
  if (!silence) return null;
  return {
    startOffsetMs: Math.max(0, silence.leading - retainedSilenceMs),
    endOffsetMs: Math.max(0, silence.trailing - retainedSilenceMs)
  };
}
